#include <stdio.h>
#include <string.h>

int main() {
    char s[100005];
    if (fgets(s, sizeof(s), stdin) == NULL) { printf("0\n"); return 0; }
    int len = strlen(s);
    while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) len--;
    int last_pos[256];
    memset(last_pos, -1, sizeof(last_pos));
    int max_len = 0, start = 0;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)s[i];
        if (last_pos[c] >= start) {
            start = last_pos[c] + 1;
        }
        last_pos[c] = i;
        int curr = i - start + 1;
        if (curr > max_len) max_len = curr;
    }
    printf("%d\n", max_len);
    return 0;
}
